(function (window,$) { "use strict";const Portfolio = window.Portfolio = window.Portfolio || {};Portfolio.config = {email: "umairshaikh7738@gmail.com",phone: "+917738635355",whatsapp: "917738635355",linkedin: "https://www.linkedin.com/in/umair-shaikh-9b2054254",previousPortfolio: "https://umair7738portfolio.free.nf",github: "https://github.com/umair7738",codepen: "https://codepen.io/umair7738"};Portfolio.utils = {escapeHtml(value) {return String(value || "").replace(/[&<>'"]/g, function (char) {
        return ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#039;", '"': "&quot;" })[char];
      });
    },

    slugify(value) {
      return String(value || "").toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
    },

    prefersReducedMotion() {
      const preference = document.documentElement.dataset.motion;
      if (preference === "full") return false;
      if (preference === "reduced") return true;
      return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    },

    refreshIcons() {
      if (window.lucide) {
        window.lucide.createIcons({ attrs: { "stroke-width": 1.7 } });
      }
    },

    splitCharacters(selector) {
      document.querySelectorAll(selector).forEach(function (element) {
        if (element.dataset.splitReady) return;
        const label = element.textContent.trim();
        element.setAttribute("aria-label", label);
        element.innerHTML = Array.from(label).map(function (char) {
          const output = char === " " ? "&nbsp;" : Portfolio.utils.escapeHtml(char);
          return '<span class="char" aria-hidden="true">' + output + "</span>";
        }).join("");
        element.dataset.splitReady = "true";
      });
    },

    splitWords(selector) {
      document.querySelectorAll(selector).forEach(function (element) {
        if (element.dataset.splitReady) return;
        const label = element.textContent.trim();
        element.setAttribute("aria-label", label);
        element.innerHTML = label.split(/\s+/).map(function (word) {
          return '<span class="word" aria-hidden="true"><span class="word-inner">' + Portfolio.utils.escapeHtml(word) + "</span></span>";
        }).join(" ");
        element.dataset.splitReady = "true";
      });
    },

    getQuery(name) {
      return new URLSearchParams(window.location.search).get(name);
    }
  };

  Portfolio.loadComponents = function () {
    const elements = Array.from(document.querySelectorAll("[data-component]"));
    return Promise.all(elements.map(function (element) {
      const component = element.dataset.component;
      return new Promise(function (resolve) {
        $(element).load("components/" + component + ".html", function (_response, status) {
          if (status === "error") {
            element.innerHTML = "";
          }
          resolve();
        });
      });
    }));
  };

  Portfolio.hydrateGlobalContent = function () {
    document.querySelectorAll("[data-current-year]").forEach(function (node) {
      node.textContent = new Date().getFullYear();
    });

    const service = Portfolio.utils.getQuery("service");
    const projectType = document.querySelector("#projectType");
    if (service && projectType) {
      const readable = service.replace(/-/g, " ");
      Array.from(projectType.options).some(function (option) {
        if (option.textContent.toLowerCase().includes(readable.toLowerCase())) {
          option.selected = true;
          return true;
        }
        return false;
      });
    }

    document.querySelectorAll("[data-profile]").forEach(function (node) {
      const url = Portfolio.config[node.dataset.profile];
      if (!url) {
        node.hidden = true;
      } else {
        node.href = url;
      }
    });
  };
})(window, window.jQuery);

(function (window, $) {
  "use strict";

  const Portfolio = window.Portfolio = window.Portfolio || {};

  Portfolio.Navigation = {
    init() {
      this.setActiveLink();
      this.initMotionPreference();
      this.initTheme();
      this.initHeader();
      this.initScrollActions();
      this.initAnchorLinks();
      this.initNavIndicator();
      this.initCursor();
      this.initMagnetic();
      this.initMicroInteractions();
    },

    initMotionPreference() {
      const root = document.documentElement;
      const stored = localStorage.getItem("portfolio-motion");
      const systemReduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      const initial = stored || (systemReduced ? "reduced" : "full");
      root.dataset.motion = initial;

      document.querySelectorAll("[data-motion-toggle]").forEach(function (button) {
        const sync = function () {
          const reduced = root.dataset.motion === "reduced";
          button.setAttribute("aria-pressed", String(!reduced));
          button.setAttribute("aria-label", reduced ? "Enable full motion" : "Reduce motion");
          button.title = reduced ? "Motion is reduced — click to enable" : "Full motion is enabled — click to reduce";
        };
        sync();
        button.addEventListener("click", function () {
          const next = root.dataset.motion === "reduced" ? "full" : "reduced";
          root.dataset.motion = next;
          localStorage.setItem("portfolio-motion", next);
          sync();
          if (window.gsap && next === "full") window.gsap.fromTo(button, { scale: .78, rotate: -18 }, { scale: 1, rotate: 0, duration: .5, ease: "back.out(2)" });
          window.setTimeout(function () { window.location.reload(); }, next === "full" ? 180 : 0);
        });
      });
    },

    setActiveLink() {
      const page = document.body.dataset.page || "home";
      document.querySelectorAll('[data-nav="' + page + '"]').forEach(function (link) {
        link.classList.add("active");
        link.setAttribute("aria-current", "page");
      });
    },

    initTheme() {
      const root = document.documentElement;
      const stored = localStorage.getItem("portfolio-theme");
      const initial = stored || "dark";
      root.dataset.theme = initial;

      document.querySelectorAll(".theme-toggle").forEach(function (button) {
        button.setAttribute("aria-pressed", String(initial === "light"));
        button.addEventListener("click", function () {
          const next = root.dataset.theme === "light" ? "dark" : "light";
          root.dataset.theme = next;
          localStorage.setItem("portfolio-theme", next);
          button.setAttribute("aria-pressed", String(next === "light"));
          if (window.gsap && !Portfolio.utils.prefersReducedMotion()) {
            window.gsap.fromTo(button, { rotate: -24, scale: .82 }, { rotate: 0, scale: 1, duration: .55, ease: "back.out(2)" });
          }
        });
      });
    },

    initHeader() {
      const header = document.querySelector("[data-site-header]");
      if (!header) return;
      let previous = window.scrollY;
      const update = function () {
        const current = window.scrollY;
        header.classList.toggle("is-scrolled", current > 18);
        header.classList.toggle("is-hidden", current > previous && current > 180);
        previous = Math.max(0, current);
      };
      window.addEventListener("scroll", update, { passive: true });
      update();
    },

    initScrollActions() {
      const buttons = document.querySelectorAll("[data-back-to-top], [data-back-top-inline]");
      const floating = document.querySelector("[data-back-to-top]");

      buttons.forEach(function (button) {
        button.addEventListener("click", function () {
          const start = window.scrollY;
          const duration = Math.min(2.8, Math.max(1.25, start / 2200));
          if (floating) floating.classList.add("is-returning");
          if (window.portfolioLenis) {
            window.portfolioLenis.scrollTo(0, {
              duration: duration,
              easing: function (value) { return 1 - Math.pow(1 - value, 4); },
              onComplete: function () { if (floating) floating.classList.remove("is-returning"); }
            });
          } else if (window.gsap) {
            const state = { value: start };
            window.gsap.to(state, {
              value: 0,
              duration: duration,
              ease: "power4.inOut",
              onUpdate: function () { window.scrollTo(0, state.value); },
              onComplete: function () { if (floating) floating.classList.remove("is-returning"); }
            });
          } else {
            window.scrollTo({ top: 0, behavior: "smooth" });
            window.setTimeout(function () { if (floating) floating.classList.remove("is-returning"); }, duration * 1000);
          }
        });
      });

      const update = function () {
        const total = document.documentElement.scrollHeight - window.innerHeight;
        const ratio = total > 0 ? window.scrollY / total : 0;
        if (floating) floating.classList.toggle("visible", window.scrollY > 500);
        if (floating) {
          floating.style.setProperty("--water-y", (100 - ratio * 100).toFixed(2) + "%");
          floating.setAttribute("aria-label", "Back to top — " + Math.round(ratio * 100) + "% page progress");
        }
      };
      window.addEventListener("scroll", update, { passive: true });
      update();
    },

    initAnchorLinks() {
      $(document).on("click", 'a[href^="#"]', function (event) {
        const id = this.getAttribute("href");
        if (!id || id === "#") return;
        const target = document.querySelector(id);
        if (!target) return;
        event.preventDefault();
        if (window.portfolioLenis) window.portfolioLenis.scrollTo(target, { offset: -90, duration: 1.1 });
        else target.scrollIntoView({ behavior: "smooth" });
      });
    },

    initNavIndicator() {
      const nav = document.querySelector(".desktop-nav");
      if (!nav || Portfolio.utils.prefersReducedMotion()) return;
      const links = Array.from(nav.querySelectorAll("a"));
      const active = nav.querySelector("a.active") || links[0];
      const pill = document.createElement("span");
      pill.className = "nav-motion-pill";
      nav.prepend(pill);
      nav.classList.add("has-motion-pill");

      const moveTo = function (link, immediate) {
        if (!link) return;
        const values = { x: link.offsetLeft, y: link.offsetTop, width: link.offsetWidth, height: link.offsetHeight };
        if (window.gsap) window.gsap.to(pill, Object.assign(values, { duration: immediate ? 0 : .42, ease: "power3.out", overwrite: true }));
        else Object.assign(pill.style, { left: values.x + "px", top: values.y + "px", width: values.width + "px", height: values.height + "px" });
      };

      moveTo(active, true);
      links.forEach(function (link) { link.addEventListener("mouseenter", function () { moveTo(link); }); });
      nav.addEventListener("mouseleave", function () { moveTo(active); });
      window.addEventListener("resize", function () { moveTo(active, true); }, { passive: true });
    },

    initCursor() {
      if (window.matchMedia("(hover: none), (pointer: coarse)").matches || Portfolio.utils.prefersReducedMotion()) return;

      const dot = document.createElement("div");
      const ring = document.createElement("div");
      const label = document.createElement("span");
      dot.className = "cursor-dot";
      ring.className = "cursor-ring";
      label.className = "cursor-label";
      ring.append(label);
      document.body.append(dot, ring);
      document.body.classList.add("motion-enabled");

      let x = -100, y = -100, ringX = -100, ringY = -100;
      document.addEventListener("mousemove", function (event) {
        x = event.clientX;
        y = event.clientY;
        dot.style.opacity = "1";
        ring.style.opacity = "1";
      });

      const render = function () {
        ringX += (x - ringX) * .17;
        ringY += (y - ringY) * .17;
        const half = ring.offsetWidth / 2;
        dot.style.transform = "translate3d(" + (x - 3) + "px," + (y - 3) + "px,0)";
        ring.style.transform = "translate3d(" + (ringX - half) + "px," + (ringY - half) + "px,0)";
        window.requestAnimationFrame(render);
      };
      render();

      $(document).on("mouseenter", "a, button, input, textarea, select, .project-card", function () {
        const element = this;
        const cursorLabel = element.matches(".project-card, .project-visual") || element.closest(".project-card") ? "VIEW" : element.matches("input, textarea, select") ? "TYPE" : "OPEN";
        ring.classList.add("is-active");
        if (element.matches(".project-card, .project-visual") || element.closest(".project-card")) {
          label.textContent = cursorLabel;
          ring.classList.add("has-label");
        }
      });
      $(document).on("mouseleave", "a, button, input, textarea, select, .project-card", function () {
        ring.classList.remove("is-active", "has-label");
        label.textContent = "";
      });
      document.addEventListener("mouseleave", function () { dot.style.opacity = "0"; ring.style.opacity = "0"; });
    },

    initMagnetic() {
      if (window.matchMedia("(hover: none), (pointer: coarse)").matches || Portfolio.utils.prefersReducedMotion()) return;
      document.querySelectorAll(".magnetic").forEach(function (element) {
        element.addEventListener("mousemove", function (event) {
          const rect = element.getBoundingClientRect();
          const x = event.clientX - rect.left - rect.width / 2;
          const y = event.clientY - rect.top - rect.height / 2;
          if (window.gsap) window.gsap.to(element, { x: x * .16, y: y * .16, duration: .35, ease: "power2.out", overwrite: true });
        });
        element.addEventListener("mouseleave", function () {
          if (window.gsap) window.gsap.to(element, { x: 0, y: 0, duration: .65, ease: "elastic.out(1,.35)", overwrite: true });
        });
      });
    },

    initMicroInteractions() {
      const reduced = Portfolio.utils.prefersReducedMotion();

      document.querySelectorAll(".btn, .icon-btn, .filter-btn").forEach(function (element) {
        element.addEventListener("pointerdown", function (event) {
          if (reduced || !window.gsap) return;
          const rect = element.getBoundingClientRect();
          const ripple = document.createElement("span");
          ripple.className = "interaction-ripple";
          ripple.style.left = event.clientX - rect.left + "px";
          ripple.style.top = event.clientY - rect.top + "px";
          element.append(ripple);
          const scale = Math.max(rect.width, rect.height) / 12;
          window.gsap.to(ripple, { scale: scale, opacity: 0, duration: .65, ease: "power2.out", onComplete: function () { ripple.remove(); } });
        });
      });

      if (!window.matchMedia("(hover: none), (pointer: coarse)").matches && !reduced) {
        document.querySelectorAll(".feature-card, .project-card, .service-card, .skill-group, .proof-card, .horizontal-panel, .case-study-teaser").forEach(function (card) {
          card.classList.add("motion-card");
          card.addEventListener("pointermove", function (event) {
            const rect = card.getBoundingClientRect();
            const px = (event.clientX - rect.left) / rect.width;
            const py = (event.clientY - rect.top) / rect.height;
            card.style.setProperty("--pointer-x", px * 100 + "%");
            card.style.setProperty("--pointer-y", py * 100 + "%");
            if (window.gsap) {
              window.gsap.to(card, { rotateX: (py - .5) * -3.5, rotateY: (px - .5) * 4.5, transformPerspective: 900, duration: .45, ease: "power2.out", overwrite: "auto" });
              const image = card.querySelector(".project-visual img, .case-study-teaser img");
              if (image) window.gsap.to(image, { x: (px - .5) * 9, y: (py - .5) * 9, scale: 1.035, duration: .55, ease: "power2.out", overwrite: true });
            }
          });
          card.addEventListener("pointerleave", function () {
            if (!window.gsap) return;
            window.gsap.to(card, { rotateX: 0, rotateY: 0, duration: .75, ease: "elastic.out(1,.45)", overwrite: "auto" });
            const image = card.querySelector(".project-visual img, .case-study-teaser img");
            if (image) window.gsap.to(image, { x: 0, y: 0, scale: 1, duration: .7, ease: "power3.out", overwrite: true });
          });
        });
      }

      document.querySelectorAll(".mobile-menu").forEach(function (menu) {
        menu.addEventListener("shown.bs.offcanvas", function () {
          if (!window.gsap || reduced) return;
          window.gsap.fromTo(menu.querySelectorAll(".mobile-nav a"), { x: 35, opacity: 0 }, { x: 0, opacity: 1, duration: .55, stagger: .055, ease: "power3.out" });
        });
      });

      document.querySelectorAll(".premium-accordion").forEach(function (accordion) {
        accordion.addEventListener("shown.bs.collapse", function (event) {
          if (!window.gsap || reduced) return;
          window.gsap.fromTo(event.target.querySelector(".accordion-body"), { y: 10, opacity: 0 }, { y: 0, opacity: 1, duration: .42, ease: "power2.out" });
        });
      });
    }
  };
})(window, window.jQuery);

(function (window) {
  "use strict";

  const Portfolio = window.Portfolio = window.Portfolio || {};

  Portfolio.Loader = {
    play() {
      const loader = document.querySelector(".page-loader");
      if (!loader) {
        document.body.classList.remove("loading");
        return Promise.resolve();
      }

      if (Portfolio.utils.prefersReducedMotion() || !window.gsap) {
        loader.remove();
        document.body.classList.remove("loading");
        return Promise.resolve();
      }

      const isHome = document.body.dataset.page === "home";
      const duration = isHome ? 1.65 : .85;
      const count = { value: 0 };
      const percent = loader.querySelector("[data-loader-percent]");
      const status = loader.querySelector("[data-loader-status]");
      let currentStatus = "";

      const updateProgress = function () {
        const value = Math.round(count.value);
        percent.textContent = String(value).padStart(3, "0");
        const nextStatus = value < 34 ? "Loading interface" : value < 68 ? "Composing motion" : value < 94 ? "Polishing details" : "Experience ready";
        if (nextStatus !== currentStatus) {
          currentStatus = nextStatus;
          status.textContent = nextStatus;
          window.gsap.fromTo(status, { y: 7, opacity: .2 }, { y: 0, opacity: 1, duration: .28, ease: "power2.out" });
        }
      };

      return new Promise(function (resolve) {
        const timeline = window.gsap.timeline({
          defaults: { ease: "power3.out" },
          onComplete: function () {
            loader.remove();
            document.body.classList.remove("loading");
            resolve();
          }
        });

        window.gsap.set(".loader-letter", { yPercent: 115, rotate: 5 });
        window.gsap.set(".loader-topline, .loader-console, .loader-meta", { opacity: 0, y: 12 });

        timeline
          .to(".loader-topline", { opacity: 1, y: 0, duration: .45 })
          .to(".loader-letter", { yPercent: 0, rotate: 0, duration: .9, stagger: .065, ease: "power4.out" }, "-=.22")
          .to(".loader-console, .loader-meta", { opacity: 1, y: 0, duration: .5, stagger: .08 }, "-=.58")
          .to(count, { value: 100, duration: duration, ease: "power2.inOut", onUpdate: updateProgress }, "-=.38")
          .to(".loader-progress span", { scaleX: 1, duration: duration, ease: "power2.inOut" }, "<")
          .to(".loader-scan", { xPercent: 180, duration: duration * .85, ease: "power1.inOut" }, "<")
          .to(".loader-stage", { y: -28, opacity: 0, duration: .42, ease: "power2.in" }, "+=.08")
          .to(".loader-panel-top", { yPercent: -101, duration: .78, ease: "power4.inOut" }, "-=.05")
          .to(".loader-panel-bottom", { yPercent: 101, duration: .78, ease: "power4.inOut" }, "<")
          .to(loader, { autoAlpha: 0, duration: .12 });
      });
    }
  };
})(window);

